import {workStore} from './work-store.mjs?v=15';
import {cleanDraft} from './work-state.mjs?v=15';
import {gridExamples} from './grid-examples.mjs?v=15';
import {createRunner,displayValue} from './runner.mjs?v=15';
import {escapeHTML as e} from './engine.mjs?v=15';
const examples={
 'Add two numbers':{hint:'NUM accepts whole numbers and decimals. Enter 4 and 6.5 when prompted; the output should be 10.5.',code:'BEGIN\n  DECLARE first AS NUM\n  DECLARE second AS NUM\n  DECLARE total AS NUM\n  INPUT first\n  INPUT second\n  SET total = first + second\n  OUTPUT total\nEND'},
 'IF ELSE decision':{hint:'Try 49, then restart and try 50 to compare the decision paths.',code:'BEGIN\n  DECLARE mark AS REAL\n  INPUT mark\n  IF mark >= 50 THEN\n    OUTPUT "Pass"\n  ELSE\n    OUTPUT "Revise"\n  ENDIF\nEND'},
 'FOR and a running total':{hint:'Enter 2, 3 and 4 as the loop requests each value. The total should be 9.',code:'BEGIN\n  DECLARE i AS INTEGER\n  DECLARE value AS REAL\n  DECLARE total AS REAL\n  SET total = 0\n  FOR i = 1 TO 3\n    INPUT value\n    SET total = total + value\n  ENDFOR\n  OUTPUT total\nEND'},
 'WHILE countdown':{hint:'Enter 3 to see three loop iterations. Enter 0 after restarting to see the body skipped.',code:'BEGIN\n  DECLARE number AS INTEGER\n  INPUT number\n  WHILE number > 0 DO\n    OUTPUT number\n    SET number = number - 1\n  ENDWHILE\nEND'},
 'Sentinel average':{hint:'Enter 10, 20 and -1. The result should be 15. A first input of -1 displays No data.',code:'BEGIN\n  DECLARE value AS REAL\n  DECLARE total AS REAL\n  DECLARE count AS INTEGER\n  SET total = 0\n  SET count = 0\n  INPUT value\n  WHILE value <> -1 DO\n    SET total = total + value\n    SET count = count + 1\n    INPUT value\n  ENDWHILE\n  IF count > 0 THEN\n    OUTPUT total / count\n  ELSE\n    OUTPUT "No data"\n  ENDIF\nEND'},
 'REPEAT input validation':{hint:'Enter 101, then -5, then 70. UNTIL becomes TRUE only for a valid mark.',code:'BEGIN\n  DECLARE mark AS REAL\n  REPEAT\n    INPUT mark\n  UNTIL mark >= 0 AND mark <= 100\n  OUTPUT mark\nEND'},
 'SWITCH menu':{hint:'Enter 1, 2 or an unsupported option to explore the selected branch.',code:'BEGIN\n  DECLARE option AS INTEGER\n  INPUT option\n  SWITCH option\n    CASE 1:\n      OUTPUT "Add"\n    CASE 2:\n      OUTPUT "View"\n    DEFAULT:\n      OUTPUT "Invalid option"\n  ENDSWITCH\nEND'},
 'Boolean approval':{hint:'Enter an age, then TRUE or FALSE for approval. The condition requires age at least 16 and approval.',code:'BEGIN\n  DECLARE age AS INTEGER\n  DECLARE approved AS BOOLEAN\n  INPUT age\n  INPUT approved\n  IF age >= 16 AND approved THEN\n    OUTPUT "Eligible"\n  ELSE\n    OUTPUT "Requirements not met"\n  ENDIF\nEND'}
};
Object.assign(examples,{"Array input and total": {"hint": "Enter 2, 3 and 4. Watch values[0], values[1] and values[2] fill; the total should be 9.", "code": "BEGIN\n  DECLARE values[3] AS INTEGER\n  DECLARE i AS INTEGER\n  DECLARE total AS INTEGER = 0\n  FOR i = 0 TO 2\n    INPUT values[i]\n    SET total = total + values[i]\n  ENDFOR\n  OUTPUT total\nEND"}, "Linear search": {"hint": "Enter 11 to find index 2. Restart with 99 to see the not-found result -1.", "code": "BEGIN\n  DECLARE values[4] AS INTEGER\n  DECLARE target AS INTEGER\n  DECLARE i AS INTEGER = 0\n  DECLARE foundAt AS INTEGER = -1\n  SET values[0] = 8\n  SET values[1] = 3\n  SET values[2] = 11\n  SET values[3] = 5\n  INPUT target\n  WHILE i < 4 AND foundAt = -1 DO\n    IF values[i] = target THEN\n      SET foundAt = i\n    ENDIF\n    SET i = i + 1\n  ENDWHILE\n  OUTPUT foundAt\nEND"}, "Parallel arrays": {"hint": "Enter 1 for Neo and 72, or 2 for Amina and 88. Names and marks share the same index.", "code": "BEGIN\n  DECLARE names[3] AS STRING\n  DECLARE marks[3] AS INTEGER\n  DECLARE selected AS INTEGER\n  SET names[0] = \"Lebo\"\n  SET names[1] = \"Neo\"\n  SET names[2] = \"Amina\"\n  SET marks[0] = 65\n  SET marks[1] = 72\n  SET marks[2] = 88\n  INPUT selected\n  IF selected >= 0 AND selected < 3 THEN\n    OUTPUT names[selected], marks[selected]\n  ELSE\n    OUTPUT \"Choose an index from 0 to 2\"\n  ENDIF\nEND"}, "Bubble sort": {"hint": "Follow adjacent comparisons and swaps. The final output should be 1, 3, 5, 8.", "code": "BEGIN\n  DECLARE values[4] AS INTEGER\n  DECLARE pass AS INTEGER\n  DECLARE i AS INTEGER\n  DECLARE temp AS INTEGER\n  SET values[0] = 8\n  SET values[1] = 3\n  SET values[2] = 5\n  SET values[3] = 1\n  FOR pass = 0 TO 2\n    FOR i = 0 TO 2 - pass\n      IF values[i] > values[i + 1] THEN\n        SET temp = values[i]\n        SET values[i] = values[i + 1]\n        SET values[i + 1] = temp\n      ENDIF\n    ENDFOR\n  ENDFOR\n  OUTPUT values[0], values[1], values[2], values[3]\nEND"}});
Object.assign(examples,gridExamples);
const savedRunnerDraft=workStore.read('tracer',null,raw=>cleanDraft(raw,20000));
const session={code:savedRunnerDraft?.code??examples['Add two numbers'].code,preset:savedRunnerDraft&&Object.hasOwn(examples,savedRunnerDraft.preset)?savedRunnerDraft.preset:'Add two numbers',runner:null,history:[],position:0,waiting:null,waitingVisible:false,input:'',editorOpen:true,message:''};
function persistRunner(){workStore.write('tracer',{code:session.code,preset:session.preset});}
export function interactiveTracePage({view,crumb,sidebar,initialCode=null,openDiagram}){
 const $=selector=>view.querySelector(selector);
 if(initialCode!==null){session.code=initialCode;session.runner=null;session.history=[];session.position=0;session.waiting=null;session.waitingVisible=false;session.input='';session.editorOpen=true;session.message='Code copied from the diagram lab. Prepare it to check the supported tracing syntax.';persistRunner();}
 view.innerHTML=crumb('Interactive tracing')+`<p class="eyebrow">YOUR CODE. EVERY STEP EXPLAINED.</p><h1>Follow your logic as it runs.</h1><p class="lede">Write a program with variables, one-dimensional arrays or two-dimensional grids, supply its inputs and inspect each change. The tracer highlights the statement it just executed, or the INPUT statement waiting for you.</p><div class="button-row"><a class="button secondary" href="#trace-guided">Guided array and sorting traces</a></div><details id="runner-editor" class="panel runner-editor" ${session.editorOpen?'open':''}><summary>Edit or choose your pseudocode</summary><div class="runner-editor-head"><label class="field-label">Load an example<select id="runner-example">${session.code!==examples[session.preset].code?'<option value="" selected disabled>Your own pseudocode</option>':''}${Object.keys(examples).map(name=>`<option ${session.preset===name&&session.code===examples[name].code?'selected':''}>${e(name)}</option>`).join('')}</select></label><p id="runner-example-hint">${e(session.code===examples[session.preset].code?examples[session.preset].hint:'Custom code: prepare it, then supply the inputs requested by its INPUT statements. Choose a built-in example to replace this draft.')}</p></div><label class="field-label" for="runner-code">Your pseudocode</label><textarea id="runner-code" class="editor" spellcheck="false" maxlength="20000">${e(session.code)}</textarea><div class="button-row"><button id="runner-prepare" class="button">Prepare my code</button><button id="runner-clean" class="button secondary">Remove pasted line numbers</button><button id="runner-diagram" class="button ghost">View as a flowchart</button></div><p>Declare each variable before using it. Editing the code clears its current trace.</p></details><p class="status" role="status" id="runner-message">${e(session.message)}</p><div id="runner-workbench"></div><details class="panel syntax runner-guide"><summary>What this first interactive tracer supports</summary><p>Use one statement per line. Names are case-insensitive. Declare NUM, INTEGER, REAL, STRING or BOOLEAN variables. NUM accepts whole numbers and decimal numbers, such as 7 and 7.5; it does not accept text or Boolean values. For example: DECLARE num AS NUM. NUM also works for constants, arrays and grids. Use SET (or plain assignments), INPUT, OUTPUT, IF/ELSE/ELSEIF, FOR, WHILE, REPEAT/UNTIL and SWITCH/CASE. Constants may use CONSTANT name AS type = expression.</p><p>For arrays, write DECLARE values[3] AS INTEGER, then SET values[0] = 10 or INPUT values[i]. The number in the declaration is the length: a length of 3 has indexes 0, 1 and 2. Declare and assign an index variable before using it. Size expressions may use previously assigned variables or constants and are fixed when declared. Elements start unassigned; access one element at a time. Parallel arrays are separate arrays that use matching indexes. At most 100 elements across all arrays are supported. For a grid, write DECLARE grid[2][3] AS INTEGER, then INPUT grid[row][column] or SET grid[0][2] = 10. The first dimension is rows and the second is columns: a 2 by 3 grid has rows 0 to 1 and columns 0 to 2. Use nested loops, with a separate declared counter for each dimension. Row and column sizes are evaluated once at declaration. A grid needs both indexes on every access. Whole-array assignments, more than two dimensions and comma-separated indexes are not supported. The 100-element limit counts every grid cell (rows multiplied by columns).</p><p>Expressions support parentheses, +, -, *, /, DIV, MOD, comparisons, AND, OR and NOT. AND and OR short-circuit. Arithmetic and comparisons bind before NOT, then AND, then OR. + adds numbers or joins two strings. Type mixing is rejected. DIV truncates towards zero; MOD uses that quotient. FOR bounds are inclusive and fixed on loop entry. STEP may be a nonzero integer. FOR counters may use INTEGER or NUM, but counter values, bounds, array sizes and indexes must remain whole numbers.</p><p>INPUT asks for one value at a time. Enter TRUE/FALSE for BOOLEAN and text without quotation marks for STRING. In code, string literals need quotes. Declarations start unassigned unless you give an initial value. Previous replays recorded states; restart to try different inputs.</p><p>Methods, function calls, RETURN, classes and objects are not executed in this version. Their diagram and guided learning tools remain available. The tracer stops after 2,000 steps, 50 variables, 200 output records or 10,000 output characters. Source limits are 20,000 characters and 300 non-empty lines. Text values are limited to 2,000 characters. NUM and REAL arithmetic use browser floating-point numbers.</p><p>Everything runs locally in this browser. The pseudocode draft saves in this browser when storage is available. Inputs and trace history stay in page memory and disappear on refresh. Prepare the saved code and enter fresh inputs to start another run. Manage or clear the draft in Saved work. No AI API, student account or shared execution database is used.</p></details>`;
 sidebar();
 $('#runner-editor').ontoggle=event=>{session.editorOpen=event.currentTarget.open;};
 function message(text){session.message=text;$('#runner-message').textContent=text;}
 function invalidate(note='Code changed. Prepare it again before stepping.'){session.runner=null;session.history=[];session.position=0;session.waiting=null;session.waitingVisible=false;session.input='';message(note);render();}
 function prepare(){try{session.code=$('#runner-code').value;persistRunner();session.runner=createRunner(session.code);session.history=[session.runner.initial()];session.position=0;session.waiting=null;session.waitingVisible=false;session.input='';message('Prepared. Choose Next step to begin.');$('#runner-editor').open=false;render();}catch(err){invalidate(err.message);$('#runner-editor').open=true;}}
 function advance(raw){if(!session.runner)return;if(session.position<session.history.length-1){session.position++;session.waitingVisible=false;render();return;}
  try{const state=session.runner.step(raw);if(state.kind==='input'){session.waiting=state;session.waitingVisible=true;message(state.note);}else{session.waiting=null;session.waitingVisible=false;session.input='';session.history.push(state);session.position=session.history.length-1;message(state.note);}render();if(session.waitingVisible)$('#runner-input')?.focus();}
  catch(err){if(err.recoverable){message(err.message);$('#runner-input-error').textContent=err.message;return;}const previous=session.history.at(-1);session.history.push({...previous,kind:'error',line:err.line||previous?.line,condition:null,changed:[],note:err.message});session.position=session.history.length-1;session.waiting=null;session.waitingVisible=false;message(err.message+' Edit and prepare again, or restart.');render();}
 }
 function render(){const host=$('#runner-workbench');if(!session.history.length){host.innerHTML='<div class="panel runner-empty"><h2>Ready to explore?</h2><p>Choose an example or write your program above, then select Prepare my code.</p><p>You will see its active line, declared variables, decisions and output here.</p></div>';return;}
  const stored=session.history[session.position],atTip=session.position===session.history.length-1,state=atTip&&session.waitingVisible?session.waiting:stored,waiting=state.kind==='input';
  const changed=new Set((state.changed||[]).map(n=>n.toLowerCase()));
  const scalarValue=(v,x)=>v.type==='STRING'&&x!==undefined?JSON.stringify(x):displayValue(x);
  const cell=(v,x,indexes)=>{const suffix=indexes.map(i=>`[${i}]`).join(''),name=v.name+suffix,active=waiting&&state.name.toLowerCase()===name.toLowerCase(),updated=changed.has(name.toLowerCase());return {classes:`runner-array-cell ${updated?'runner-element-changed':''} ${active?'runner-element-input':''}`,content:`<small>${e(suffix)}${updated?' - changed':active?' - input':''}</small><code>${e(scalarValue(v,x))}</code>`};};
  const arrayValue=v=>{const dims=v.dimensions||[v.value.length];if(dims.length===2)return `<div class="runner-matrix-scroll"><table class="runner-matrix"><caption>${e(v.name)}: ${dims[0]} rows by ${dims[1]} columns</caption><thead><tr><th scope="col">Row / column</th>${Array.from({length:dims[1]},(_,c)=>`<th scope="col">Column ${c}</th>`).join('')}</tr></thead><tbody>${Array.from({length:dims[0]},(_,r)=>`<tr><th scope="row">Row ${r}</th>${Array.from({length:dims[1]},(_,c)=>{const item=cell(v,v.value[r*dims[1]+c],[r,c]);return `<td class="${item.classes}">${item.content}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;return `<div class="runner-array" role="list" aria-label="${e(v.name)} elements">${v.value.map((x,i)=>{const item=cell(v,x,[i]);return `<div role="listitem" class="${item.classes}">${item.content}</div>`;}).join('')}</div>`;};
  const listed=state.variables.filter(v=>v.dimensions?.length!==2),grids=state.variables.filter(v=>v.dimensions?.length===2);
  const value=v=>v.type==='STRING'&&v.value!==undefined?JSON.stringify(v.value):displayValue(v.value);
  host.innerHTML=`<div class="runner-controls"><div class="button-row"><button class="button secondary" id="runner-prev" ${session.position===0&&!waiting?'disabled':''}>Previous step</button><button class="button" id="runner-next" ${waiting||(atTip&&['done','error'].includes(state.kind))?'disabled':''}>${atTip?'Next step':'Next recorded step'}</button><button class="button secondary" id="runner-restart">Restart with new inputs</button><button class="button ghost" id="runner-edit">Edit code</button></div><p class="runner-state-label" role="status">${state.kind==='ready'?'Ready':waiting?'Waiting for input':state.kind==='done'?'Completed':state.kind==='error'?'Stopped with an error':'Step '+state.steps}${state.line?' - line '+state.line:''}${state.condition===true?' - condition TRUE':state.condition===false?' - condition FALSE':''}</p></div><div class="runner-layout"><section class="panel"><h2>Your running program</h2><p class="runner-small">The highlighted line is the last executed statement or the pending INPUT.</p><pre class="runner-source"><code>${session.code.split('\n').map((line,i)=>`<span class="line-code ${state.line===i+1?'trace-current':''}" ${state.line===i+1?'aria-current="step"':''}><span class="ln">${i+1}</span>${e(line)}</span>`).join('')}</code></pre></section><section class="panel"><h2>Current state</h2><p class="runner-explanation ${state.kind==='error'?'runner-error':''}" role="status">${e(state.note)}</p>${waiting?`<form id="runner-input-form" class="runner-input-form"><label class="field-label" for="runner-input">Input for ${e(state.name)} (${e(state.type)})</label><input id="runner-input" type="text" autocomplete="off" maxlength="2000" value="${e(session.input)}" aria-describedby="runner-input-help runner-input-error"><p id="runner-input-help">${state.type==='BOOLEAN'?'Enter TRUE or FALSE.':state.type==='STRING'?'Enter text without quotation marks.':state.type==='INTEGER'?'Enter a whole number.':'Enter a number, using a decimal point if needed.'}</p><button class="button" type="submit">Use this input</button><p id="runner-input-error" class="runner-error" role="status"></p></form>`:''}<h3>Variables</h3><div class="scroll-table"><table class="runner-variables"><thead><tr><th>Name</th><th>Type</th><th>Value</th></tr></thead><tbody>${listed.length?listed.map(v=>`<tr class="${changed.has(v.name.toLowerCase())?'runner-changed':''}"><th scope="row">${e(v.name)}${v.constant?' <small>(constant)</small>':''}</th><td>${e(v.type)}${v.array?(v.dimensions||[v.value.length]).map(d=>`[${d}]`).join(''):""}</td><td>${v.array?arrayValue(v):`<code>${e(value(v))}</code>`}</td></tr>`).join(''):`<tr><td colspan="3">${grids.length?'Grid values are shown below.':'No declarations executed yet.'}</td></tr>`}</tbody></table></div>${grids.map(v=>`<section class="runner-grid-state ${changed.has(v.name.toLowerCase())?'runner-grid-declared':''}"><h4>${e(v.name)} <small>${e(v.type)}${v.dimensions.map(d=>`[${d}]`).join('')}</small></h4>${arrayValue(v)}</section>`).join('')}<p class="runner-small">Highlighted rows were declared or changed in this step. Array elements show their indexes; green marks a changed element and amber marks a pending input.</p><h3>Output</h3><pre class="runner-output">${e(state.output.length?state.output.join('\n'):'No output yet')}</pre></section></div><details class="panel runner-history"><summary>Recorded trace history (${session.history.length-1} events)</summary><p>Previous and Next replay these states without running them again. Only the most recent 40 rows up to this position are shown.</p><div class="scroll-table"><table><thead><tr><th>Step</th><th>Line</th><th>What happened</th></tr></thead><tbody>${session.history.slice(Math.max(1,session.position-39),session.position+1).map(s=>`<tr><td>${s.steps}</td><td>${s.line??'-'}</td><td>${e(s.note)}</td></tr>`).join('')}</tbody></table></div></details>`;
  $('#runner-prev').onclick=()=>{if(waiting){session.waitingVisible=false;}else if(session.position>0)session.position--;message('Reviewing a recorded state. Restart to change inputs.');render();};$('#runner-next').onclick=()=>advance();$('#runner-restart').onclick=prepare;$('#runner-edit').onclick=()=>{$('#runner-editor').open=true;$('#runner-code').focus();};
  if(waiting){$('#runner-input').oninput=event=>{session.input=event.target.value;};$('#runner-input-form').onsubmit=event=>{event.preventDefault();session.input=$('#runner-input').value;advance(session.input);};}
 }
 $('#runner-code').oninput=event=>{session.code=event.target.value;$('#runner-example-hint').textContent='Custom code: prepare it, then supply the inputs requested by its INPUT statements.';persistRunner();invalidate();};$('#runner-example').onchange=event=>{session.preset=event.target.value;session.code=examples[session.preset].code;$('#runner-code').value=session.code;$('#runner-example-hint').textContent=examples[session.preset].hint;persistRunner();invalidate('Example loaded. Prepare it to begin.');};$('#runner-prepare').onclick=prepare;$('#runner-clean').onclick=()=>{const cleaned=$('#runner-code').value.replace(/^\s*\d{1,3}[.)]?\s+(?=[A-Za-z_/])/gm,'');if(cleaned===$('#runner-code').value){message('No leading line-number labels were found.');return;}session.code=cleaned;$('#runner-code').value=cleaned;persistRunner();invalidate('Line-number labels removed. Review the code, then prepare it.');};$('#runner-diagram').onclick=()=>openDiagram($('#runner-code').value);render();
}

